using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckDanceOff {
public enum DancePhase{CountIn,Song,RoundResult,Complete}
public sealed class DanceMatch:SportsEventSession {
 public DanceSongLibrary library;public AudioSource music,calibrationAudio;public DanceTruckRig[] dancers;public DanceHud rhythmHud;public Camera stageCamera;public TMPro.TMP_Text songChoice,formatChoice,calibrationText;
 [Range(.06f,.18f),Tooltip("GREAT timing tolerance in seconds; PERFECT stays at 45ms.")]public float greatTimingWindow=.12f;
 [Range(.16f,.28f),Tooltip("GOOD early/late tolerance in seconds, shared by human and AI judgments.")]public float goodTimingWindow=.21f;
 public DanceRules[] Rules{get;private set;}public DancePhase Phase{get;private set;}public DanceSongLibrary.Song Song{get;private set;}public double SongTime{get;private set;}public int Round{get;private set;}public int Format{get;private set;}public float CalibrationMs{get;private set;}public readonly int[] total=new int[4];
 public bool Calibrating=>calibrating;public double CalibrationReferenceDSP=>calibrationStart;public int CalibrationSamples=>taps.Count;
 public int PhysicalRoutines{get{int n=0;foreach(var d in dancers)n+=d.RoutineChanges;return n;}}
 struct Hit{public double time;public int bits;public bool down;public Hit(double t,int b,bool d){time=t;bits=b;down=d;}}
 readonly List<Hit>[] queued={new List<Hit>(),new List<Hit>(),new List<Hit>(),new List<Hit>()};readonly DanceInputRouter[] input=new DanceInputRouter[4];readonly int[] held=new int[4];readonly double[] judgedClock=new double[4];readonly bool[] bot=new bool[4];readonly StringBuilder labels=new StringBuilder();double startDSP,pausedAt,leadUntil,songFloor;float resultAge;int firstSong;bool configured,calibrating;int calibrationSlot=-1;double calibrationStart,lastTap=-1;readonly List<double> taps=new List<double>();
 const string Prefix="TruckDanceOff.Presentation.v1.";
 public override string Title=>"TRUCK DANCE-OFF";public override int MinimumPlayers=>1;public override int MaximumPlayers=>4;public override int OptionCount=>28;public override int WeatherCount=>1;public override bool UsesAction=>false;
 public override string OptionLabel=>(library!=null?library.Get(option%7).title.ToUpperInvariant():"SONG")+" · "+new[]{"EASY","NORMAL","HARD","INSANE"}[Mathf.Clamp(option/7,0,3)];
 public override bool BroadcastHeaderVisible=>false;public override bool BroadcastStatusVisible=>false;public override bool BroadcastStandingsVisible=>false;
 public override string Help=>"FOUR LANES. SIX TONS OF RHYTHM.\nMatch LEFT / DOWN / UP / RIGHT on the beat. Keyboard uses your assigned movement keys; a whole controller uses D-pad or West / South / North / East face buttons. Shared controllers use each participant's owned stick. Diagonal chords never require opposite stick directions. Hold long notes through their tail.\n\nPerfect ±45ms · Great ±90ms · Good ±160ms. Wrong presses break your combo and cost 20 points; every scored note is judged once from input timestamps, never from an animation or frame rate. During FREESTYLE, vary directions and diagonals in time: repeated mashing earns nothing.\n\nSeven original complete genre tracks, four charts each. SINGLE SONG or THREE-SONG SHOW; highest total wins, ties share the stage. Use CALIBRATE in setup: listen to the pulse and tap your assigned lane to measure your display/audio/input delay, or adjust the saved timing offset.\n\nSuccessful input drives cute truck dances, then donuts, wheelies and breakdance stunts as combos build. Misses show a shy recovery. Pause and reconnect preserve song position; release all lanes before the resume count-in. Each truck owns its lanes, score and platform. One shared stage camera and one audio listener. Offline only.";
 public override string Header=>Title+" · "+(Song==null?OptionLabel:Song.title.ToUpperInvariant()+" / "+Song.genre.ToUpperInvariant());
 public override string Status=>Phase==DancePhase.CountIn?"GET READY · "+Math.Max(1,Math.Ceiling(leadUntil-AudioSettings.dspTime)):Phase==DancePhase.RoundResult?"SONG COMPLETE · SCORES LOCKED":Phase==DancePhase.Song&&SongTime>=Song.freestyleStart&&SongTime<Song.freestyleEnd?"FREESTYLE · VARY YOUR MOVES ON THE BEAT":Phase==DancePhase.Song?"ROUND "+Round+" / "+(Format==0?1:3):"SHOW COMPLETE";
 public override string Standings{get{labels.Clear();for(int i=0;i<setup.count;i++)labels.Append(setup.players[i].name).Append("  ").Append(total[i]+(Phase==DancePhase.Song||Phase==DancePhase.CountIn?Rules?[i].Score??0:0)).Append(" PTS").Append(i+1==setup.count?"":"\n");return labels.ToString();}}
 public override string Results{get{int best=int.MinValue;for(int i=0;i<setup.count;i++)best=Math.Max(best,total[i]);labels.Clear();for(int i=0;i<setup.count;i++)if(total[i]==best)labels.Append(setup.players[i].name).Append("  ");return labels.ToString()+"TAKE THE STAGE!\n\n"+Standings;}}
 public override bool TryReadScoreCard(int card,out string value,out string detail){value=(total[card]+(Phase==DancePhase.Song||Phase==DancePhase.CountIn?Rules?[card].Score??0:0)).ToString("N0");detail=Rules==null?"READY":"COMBO "+Rules[card].Combo+" · "+Rules[card].LastGrade.ToString().ToUpperInvariant();return true;}
 public override string ControlCaption(int slot){var p=setup.players[slot];return p.source==BowlingSource.WholeController?"D-PAD / WEST SOUTH NORTH EAST":Controls(slot);}
 protected override void Awake(){base.Awake();Format=SportsPrefs.GetInt(Prefix+"Format",0);CalibrationMs=Mathf.Clamp(SportsPrefs.GetFloat(Prefix+"CalibrationMs",0),-200,200);}
 protected override void BeginGame(){library.Validate();StopCalibration();DisposeInputs();Array.Clear(total,0,total.Length);firstSong=option%7;Round=0;for(int i=0;i<setup.count;i++){int slot=i;bot[i]=setup.players[i].source==BowlingSource.AI;if(!bot[i])input[i]=new DanceInputRouter(setup.players[i],(at,bits,down)=>Receive(slot,at,bits,down));}configured=true;BeginSong();}
 void BeginSong(){Round++;Song=library.Get((firstSong+Round-1)%7);Rules=new DanceRules[setup.count];for(int i=0;i<4;i++){dancers[i].gameObject.SetActive(i<setup.count);queued[i].Clear();held[i]=0;judgedClock[i]=-10;if(i>=setup.count)continue;int slot=i;Rules[i]=new DanceRules(Song.charts[option/7].notes,Mathf.Clamp(greatTimingWindow,.06f,.18f),Mathf.Max(Mathf.Clamp(goodTimingWindow,.16f,.28f),Mathf.Clamp(greatTimingWindow,.06f,.18f)));Rules[i].Judged+=(n,g)=>{var note=Rules[slot].Note(n);dancers[slot].Hit(g,Rules[slot].Combo,note.mask,note.time,Song.Beat);rhythmHud?.Judged(slot,g);if(g==DanceGrade.Perfect)Pulse(slot,.08f,.025f);};Rules[i].Freestyled+=mask=>dancers[slot].Hit(DanceGrade.Perfect,Rules[slot].Combo+Rules[slot].FreestyleHits,mask,SongTime,Song.Beat,true);dancers[i].Begin(setup.players[i].color);input[i]?.Gate();if(bot[i])PlanAI(i);}
  SongTime=songFloor=0;music.Stop();music.clip=Song.music;music.pitch=1;music.timeSamples=0;leadUntil=AudioSettings.dspTime+Song.Beat*4;startDSP=leadUntil;music.PlayScheduled(startDSP);Phase=DancePhase.CountIn;rhythmHud?.Rebuild(this);Gate();
 }
 void PlanAI(int slot){var r=new System.Random(7919+Round*37+slot*199+(int)setup.players[slot].difficulty*13);int level=(int)setup.players[slot].difficulty;double miss=level==0?.16:level==1?.07:.025,spread=level==0?.18:level==1?.11:.06;foreach(var n in Song.charts[option/7].notes){if(r.NextDouble()<miss)continue;double at=n.time+(r.NextDouble()*2-1)*spread;queued[slot].Add(new Hit(at,n.mask,true));queued[slot].Add(new Hit(Math.Max(at+.1,n.time+n.duration+.02),n.mask,false));}for(double t=Song.freestyleStart;t<Song.freestyleEnd;t+=Song.Beat)if(r.NextDouble()>.18){int m=1<<r.Next(4);queued[slot].Add(new Hit(t+(r.NextDouble()-.5)*spread,m,true));queued[slot].Add(new Hit(t+.12,m,false));}queued[slot].Sort((a,b)=>a.time.CompareTo(b.time));}
 void Receive(int slot,double realAt,int bits,bool down){if(calibrating){if(down&&slot==calibrationSlot)CalibrationTap(realAt);return;}if(!Live||!configured||Phase!=DancePhase.Song&&Phase!=DancePhase.CountIn)return;double at=realAt+(AudioSettings.dspTime-Time.realtimeSinceStartupAsDouble)-startDSP-CalibrationMs*.001;if(AudioSettings.dspTime<leadUntil){if(songFloor>0)held[slot]=down?held[slot]|bits:held[slot]&~bits;return;}if(at<songFloor)return;var list=queued[slot];var hit=new Hit(at,bits,down);int i=list.Count;while(i>0&&list[i-1].time>at)i--;list.Insert(i,hit);}
 protected override void Present(float dt){if(calibrating){input[calibrationSlot]?.Tick(Time.unscaledDeltaTime);if(!Ready(calibrationSlot)||menus.Screen!=SportsEventScreen.Setup)StopCalibration();return;}if(!configured)return;music.volume=settings.music;if(!Live)return;foreach(var router in input)router?.Tick(Time.unscaledDeltaTime);if(Phase==DancePhase.RoundResult){resultAge+=Time.unscaledDeltaTime;for(int i=0;i<setup.count;i++)dancers[i].Pose(SongTime+resultAge);if(resultAge>=4){if(Round>=(Format==0?1:3)){Phase=DancePhase.Complete;EndMatch();}else BeginSong();}return;}if(Phase!=DancePhase.CountIn&&Phase!=DancePhase.Song)return;double now=AudioSettings.dspTime;SongTime=Math.Max(songFloor,now-startDSP);if(now>=leadUntil)Phase=DancePhase.Song;double horizon=SongTime-.03;
  JudgeTo(horizon);
  rhythmHud?.Draw(this);if(SongTime>Song.duration+.3){for(int i=0;i<setup.count;i++)total[i]+=Rules[i].Score;int best=0;for(int i=0;i<setup.count;i++)best=Math.Max(best,Rules[i].Score);for(int i=0;i<setup.count;i++)if(Rules[i].Score==best)dancers[i].Hit(DanceGrade.Perfect,8,1,SongTime,Song.Beat);Phase=DancePhase.RoundResult;resultAge=0;music.Stop();feedback.Play(5,0,true);}
 }
 void JudgeTo(double horizon){
  for(int i=0;i<setup.count;i++){var rule=Rules[i];var q=queued[i];while(q.Count>0&&q[0].time<=horizon){var e=q[0];q.RemoveAt(0);double at=Math.Max(judgedClock[i],e.time);int pressed=e.down?e.bits&~held[i]:0;held[i]=e.down?held[i]|e.bits:held[i]&~e.bits;if(at>=Song.freestyleStart&&at<Song.freestyleEnd){if(pressed!=0)rule.Freestyle(at,Song.Beat,pressed,Song.freestyleStart,Song.freestyleEnd);rule.Step(at,0,held[i]);}else rule.Step(at,pressed,held[i]);judgedClock[i]=at;}if(horizon>=judgedClock[i]){rule.Step(horizon,0,held[i]);judgedClock[i]=horizon;}dancers[i].Pose(SongTime);}
 }
 protected override void Simulate(float dt){}
 protected override void SetPaused(bool pause){if(!configured)return;if(pause){if(Phase==DancePhase.Song||Phase==DancePhase.CountIn){SongTime=Math.Max(songFloor,AudioSettings.dspTime-startDSP);JudgeTo(SongTime);}pausedAt=SongTime;music.Pause();}else{RebindHumanInputs();if(Phase==DancePhase.Song||Phase==DancePhase.CountIn){music.Stop();music.timeSamples=Mathf.Clamp((int)(pausedAt*music.clip.frequency),0,music.clip.samples-1);songFloor=pausedAt;leadUntil=AudioSettings.dspTime+1.2;startDSP=leadUntil-pausedAt;music.PlayScheduled(leadUntil);Phase=DancePhase.CountIn;}}}
 protected override void StopGame(){configured=false;StopCalibration();music?.Stop();DisposeInputs();if(dancers!=null)foreach(var d in dancers)if(d!=null)d.Stop();rhythmHud?.Hide();}
 void RebindHumanInputs(){for(int i=0;i<setup.count;i++){if(bot[i])continue;input[i]?.Dispose();input[i]=null;held[i]=0;queued[i].Clear();if(Ready(i)){int slot=i;input[i]=new DanceInputRouter(setup.players[i],(at,bits,down)=>Receive(slot,at,bits,down));}}}
 void DisposeInputs(){for(int i=0;i<4;i++){input[i]?.Dispose();input[i]=null;queued[i].Clear();held[i]=0;}}
 protected override void OnDestroy(){StopCalibration();DisposeInputs();base.OnDestroy();}
 void BeginCalibration(){for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI&&Ready(i)){calibrationSlot=i;break;}if(calibrationSlot<0){calibrationText.text="Assign a human source before calibration";return;}DisposeInputs();int slot=calibrationSlot;input[slot]=new DanceInputRouter(setup.players[slot],(at,bits,down)=>Receive(slot,at,bits,down));taps.Clear();lastTap=-1;calibrationStart=AudioSettings.dspTime+1;calibrating=true;calibrationAudio.loop=true;calibrationAudio.volume=settings.music;calibrationAudio.PlayScheduled(calibrationStart);calibrationText.text="Listen, then tap a lane with each pulse · 0 / 12";}
 void CalibrationTap(double realAt){double dsp=realAt+AudioSettings.dspTime-Time.realtimeSinceStartupAsDouble;double position=dsp-calibrationStart,beat=Math.Round(position);if(position<-.3||beat==lastTap||Math.Abs(position-beat)>.4)return;lastTap=beat;taps.Add((position-beat)*1000);calibrationText.text="Tap with the pulse · "+taps.Count+" / 12";if(taps.Count<12)return;var accepted=taps.GetRange(2,10);accepted.Sort();CalibrationMs=Mathf.Clamp((float)((accepted[4]+accepted[5])*.5),-200,200);SportsPrefs.SetFloat(Prefix+"CalibrationMs",CalibrationMs);SportsPrefs.Save();StopCalibration();RefreshExtraUI();}
 void StopCalibration(){calibrationAudio?.Stop();calibrating=false;if(calibrationSlot>=0){input[calibrationSlot]?.Dispose();input[calibrationSlot]=null;}calibrationSlot=-1;}
 public override void RefreshExtraUI(){if(formatChoice!=null)formatChoice.text=Format==0?"SINGLE SONG":"THREE-SONG SHOW";if(calibrationText!=null)calibrationText.text="TIMING OFFSET "+CalibrationMs.ToString("+0;-0;0")+" ms";}
 public override void ExtraAction(string key){if(key=="dance-reset-calibration"){CalibrationMs=0;SportsPrefs.SetFloat(Prefix+"CalibrationMs",0);SportsPrefs.Save();RefreshExtraUI();return;}if(key=="dance-calibrate"){if(calibrating)StopCalibration();else BeginCalibration();return;}if(key=="dance-format"){Format=1-Format;SportsPrefs.SetInt(Prefix+"Format",Format);}else if(key=="dance-offset-")CalibrationMs=Mathf.Max(-200,CalibrationMs-5);else if(key=="dance-offset+")CalibrationMs=Mathf.Min(200,CalibrationMs+5);SportsPrefs.SetFloat(Prefix+"CalibrationMs",CalibrationMs);SportsPrefs.Save();RefreshExtraUI();menus.Dirty();}
}
}
